#!/usr/bin/env python3
"""Build dependency-free static pages. Editorial sources checked 2026-11-25."""
from html import escape
from pathlib import Path
from urllib.parse import quote_plus

E=escape
links=[('index.html','Overview'),('hotels.html','Hotels'),('restaurants.html','Dining'),('activities.html','Activities'),('plan.html','Trip plan'),('review.html','Flagged for review')]
def link(url,label): return f'<a href="{E(url,quote=True)}" target="_blank" rel="noopener noreferrer">{E(label)} ↗</a>'
def src(*pairs): return '<span class="sources">'+' '.join(link(url,label) for label,url in pairs)+'</span>'
def social(query):
 q=quote_plus(query)
 return '<span class="social">'+link('https://www.youtube.com/results?search_query='+q,'YouTube search')+link('https://www.tiktok.com/search?q='+q,'TikTok search')+link('https://www.instagram.com/explore/search/keyword/?q='+q,'Instagram search')+'</span>'
U='<span class="tag">unverified</span>'
def table(headers,rows):
 head=''.join(f'<th scope="col">{E(h)}</th>' for h in headers)
 body=''.join('<tr>'+''.join(f'<td data-label="{E(h,quote=True)}">{v}</td>' for h,v in zip(headers,row))+'</tr>' for row in rows)
 return f'<div class="table-wrap"><table><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div>'
def section(title,body,sub=''):return f'<section class="section"><div class="section-head"><div><h2>{title}</h2><p>{sub}</p></div></div>{body}</section>'
def page(filename,title,content):
 nav=''.join(f'<a href="{f}"'+(' class="active" aria-current="page"' if f==filename else '')+f'>{label}</a>' for f,label in links)
 doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="An evidence-first China trip planner for two adults in 2027."><title>{E(title)} | China, considered</title><link rel="stylesheet" href="assets/style.css"></head><body><header><div class="wrap"><div class="brand">China <b>✳</b> considered &nbsp; / &nbsp; A trip for two</div><nav aria-label="Main navigation">{nav}</nav></div></header><main class="wrap">{content}</main><footer><div class="wrap">Research snapshot: 25 November 2026 · Times are local · Verify schedules and rates before booking. <a href="review.html">Methods &amp; limitations</a></div></footer></body></html>'''
 Path(filename).write_text(doc,encoding='utf-8')

holiday='https://www.gov.cn/zhengce/content/202611/content_7085101.htm'
sh='https://guide.michelin.com/en/cn/shanghai-municipality/restaurants'
bj='https://guide.michelin.com/en/cn/beijing-municipality/beijing/restaurants'
park='https://www.hyatt.com/park-hyatt/en-US/shaph-park-hyatt-shanghai/rooms'
beijing='https://www.fourseasons.com/beijing/accommodations/specialty-suites/beijing-suite/'
gu='https://www.fourseasons.com/guangzhou/accommodations/rooms/tower_room/'
hz='https://www.fourseasons.com/hangzhoucentre/accommodations/suites/hangzhou-suite/'
tai='https://guide.michelin.com/en/shanghai-municipality/shanghai/restaurant/taian-table'
faq='https://sh.taian-table.cn/faq/'
king='https://guide.michelin.com/en/beijing-municipality/beijing/restaurant/king-s-joy'
yuge='https://guide.michelin.com/en/shanghai-municipality/shanghai/restaurant/yu-ge-zhan-jiang-jingan'
aster='https://guide.michelin.com/en/shanghai-municipality/shanghai/restaurant/aster-by-joshua-paris'
sm='https://www.shanghaimuseum.net/mu/frontend/pg/m/en/service/visit-west'
pm='https://intl.dpm.org.cn/visit.html?l=en'

index='''<div class="hero"><div><div class="eyebrow">The evidence-first travel brief / 2027</div><h1>China, considered.</h1><p class="lead">A clear starting point for two adults: memorable meals, thoughtful stays, and a trip built around what can actually be verified.</p><a class="button" href="plan.html">Explore the trip plan →</a></div><div class="hero-side"><div class="eyebrow">The brief</div><strong>15 February – 23 March 2027</strong><p>One to two weeks · Two adults<br>Preferred start: 15–18 February</p></div></div>
<div class="grid"><div class="card"><div class="eyebrow">A workable starting window</div><strong class="big">15–22 Feb</strong><p>Seven nights, checking out 22 February. Proposed, not a verified booking.</p></div><div class="card"><div class="eyebrow">City-wide guide snapshot</div><strong class="big">154 / 107</strong><p>Shanghai municipality / Beijing area Michelin listings. Not hotel-radius counts.</p></div><div class="card"><div class="eyebrow">Decision status</div><strong class="big">Not ready to book</strong><p>Comparable room totals and public-transit times remain unverified.</p></div></div>'''
index+=f'<div class="alert"><strong>Important:</strong> The preferred 15–18 February interval alone is shorter than one week. The proposed 15–22 February stay includes those dates. Spring Festival public holidays run 5–13 February; the official notice identifies 14 February as a makeup workday. {link(holiday,"State Council notice")}. This does not establish crowd levels or future venue hours.</div>'
index+=section('A useful place to start','''<div class="panel"><p><strong>Shanghai is a research starting point, not a winning hotel recommendation.</strong> The Guide's city-wide listing count exceeds Beijing's in this snapshot, and the shortlist has a documented king room, dining and a museum. It does not establish which hotel has the most restaurants within an hour, the least expensive stay, or a verified transit itinerary.</p></div>''')
index+=section('Explore the research','<div class="linkcards">'+''.join(f'<a class="linkcard" href="{f}"><h3>{title} <span class="arrow">→</span></h3><span>{desc}</span></a>' for f,title,desc in [('hotels.html','Hotels','Compare room features and gaps.'),('restaurants.html','Dining','Stars, Bib Gourmand and social searches.'),('activities.html','Activities','Opening times and venue exceptions.'),('plan.html','Trip plan','Dates, tradeoffs and booking method.'),('review.html','Flagged for review','Open questions and improvement ideas.')])+'</div>')
index+=section('City-wide Michelin snapshot',table(['Guide area','3★','2★','1★','Bib','Selected','Total','Official source'],[['Shanghai municipality','1','11','38','34','70','154',src(('Michelin',sh))],['Beijing and surroundings','2','5','26','32','42','107',src(('Michelin',bj))]]), 'Observed 25 November 2026. Areas differ; counts change and are not a one-hour transit ranking.')
page('index.html','Overview',index)

hotelrows=[['Park Hyatt Shanghai','Shanghai · 1 King Bed, City View','King bed; in-room bathroom with rain shower and tub; Wi-Fi',U,U,U,src(('Hyatt room details',park))],['Four Seasons Hotel Beijing','Beijing · Beijing Suite','King bed; full bathroom and powder room; Wi-Fi',U,U,U,src(('Four Seasons room details',beijing))],['Four Seasons Hotel Guangzhou','Guangzhou · Tower Room','King bed; full bathroom; Wi-Fi; capacity 2 adults',U,U,U,src(('Four Seasons room details',gu))],['Four Seasons Hotel Hangzhou at Hangzhou Centre','Hangzhou · Hangzhou Suite','King bed; full bathroom and guest bathroom; Wi-Fi; capacity 2 adults',U,U,U,src(('Four Seasons room details',hz))]]
hotels='''<div class="eyebrow">Stay / shortlist</div><h1>Rooms with room to decide.</h1><p class="lead">Four candidate room types with official descriptions. This is a shortlist, not a best-value or location ranking.</p><div class="alert"><strong>Ranking unavailable.</strong> Neither the hotel-to-restaurant transit matrix nor comparable 2027 seven-night quotes could be verified. A blank marked unverified is not zero, sold out, or proof that booking is unavailable.</div>'''
hotels+=section('Hotel comparison',table(['Hotel','City · room type','Verified features','7-night total for 2','Guide restaurants ≤60 min','Rank','Official source'],hotelrows),'Suggested comparison: check-in 15 February, checkout 22 February 2027; one room, two adults. Exact availability and private use of bathroom require confirmation.')
hotels+=section('How to make the ranking defensible','''<div class="panel"><ol class="list"><li>Enumerate current Michelin entries for each city and classify by star, Bib and Selected, without double-counting.</li><li>Route each hotel entrance to each restaurant by subway or bus on a specified 2027 date and departure time, including walking and transfers. Record provider and capture time.</li><li>Count routes of 60 minutes or less; rank by total, then show starred and non-starred subtotals separately. Do not confuse city totals with local reach.</li><li>Collect simultaneous, final seven-night totals for two adults from each official hotel, including taxes and fees, cancellation terms and room type. Compare multiple actual date windows before claiming a cheapest date or booking time.</li></ol></div>''')
page('hotels.html','Hotels',hotels)

restaurants=[['Taian Table · Shanghai','★★★ · starred','¥5,176–¥5,776 for two tasting menus, calculated from ¥2,588 / ¥2,888 per person; reference prices, all-inclusive; supplements / drinks may add cost. 2027 price unverified.','Tue–Sat dinner; bookings 18:00–20:00. Holiday exceptions unverified.',U,social('Taian Table Shanghai'),src(('Michelin',tai),('Restaurant FAQ',faq),('Restaurant','https://sh.taian-table.cn/'))],['King’s Joy · Beijing','★★ · starred',U,'Mon–Sun 11:00–22:00, per Michelin. 2027 exceptions unverified.',U,social("King's Joy Beijing"),src(('Michelin',king),('Restaurant','https://www.kingsjoy.com/'))],['Yuge · Zhanjiang (Jingan) · Shanghai','Bib Gourmand · not starred',U,U+'; Michelin mentions open until 02:00 but full schedule not confirmed.',U,social('Yuge Zhanjiang Jingan Shanghai'),src(('Michelin',yuge))],['Aster by Joshua Paris · Shanghai','Michelin Selected · not starred',U,U,U,social('Aster by Joshua Paris Shanghai'),src(('Michelin',aster),('Selected filter','https://guide.michelin.com/us/en/shanghai-municipality/shanghai/restaurants/the-plate-michelin'))]]
dining='''<div class="eyebrow">Eat / Michelin guide</div><h1>A table worth planning for.</h1><p class="lead">A small, individually checked sample—not a complete inventory of restaurants within an hour of a hotel. Michelin designations can change before travel.</p><div class="alert">Social links below are platform <strong>searches</strong>, not verified official accounts or endorsements. Hours are current source descriptions, not 2027 guarantees. All transit times are unverified.</div>'''
dining+=section('Restaurant details',table(['Restaurant','Guide distinction','Total for 2 adults','Days, hours & exceptions','Hotel transit ≤60 min','Social discovery','Official sources'],restaurants),'Prices in Chinese yuan. Source-based calculations are explicitly labelled; blank unverified values are not free.')
dining+=section('Before reserving','<div class="panel"><p>Taian Table says online reservations are available up to 90 days ahead; a ¥2,000 deposit per person is required, and special-holiday policies may differ. The restaurant says menu prices can change and its Chinese terms prevail. '+link(faq,'Read the official FAQ')+'.</p><p>The Michelin Guide’s cost symbols for the other restaurants are not an exact bill for two; no amount has been invented.</p></div>')
page('restaurants.html','Dining',dining)

activity=[['Shanghai Museum · People’s Square','Shanghai','Tue–Sun 09:00–17:00, last entry 15:00. Closed Mondays except national holidays; selected evening sessions have different hours. Exhibition restrictions through 14 Nov 2027.',U,U,social('Shanghai Museum Peoples Square'),src(('Museum visit information',sm))],['The Palace Museum · Forbidden City','Beijing','Nov–Mar: Tue–Sun 08:30–16:30, last entry 15:30. Mondays closed except national holidays; closed Chinese New Year’s Eve; irregular closures possible. Advance booking, no same-day ticket sales.','¥80 for two adult base tickets (¥40 × 2), excluding galleries; 2027 price unverified.',U,social('Palace Museum Forbidden City Beijing'),src(('Museum visit information',pm))]]
activities='''<div class="eyebrow">Explore / activity shortlist</div><h1>Leave space to discover.</h1><p class="lead">Two cultural starting points with visitor information from their operators. Neither has a verified route from a shortlisted hotel.</p><div class="alert">The one-hour requirement is <strong>not yet verified</strong>. Do not treat these suggestions as confirmed nearby activities. Social searches are not official accounts.</div>'''
activities+=section('Activities & visitor details',table(['Activity','City','Days, hours & exceptions','Total for 2 adults','Hotel transit ≤60 min','Social discovery','Official source'],activity),'Hours are local. Recheck the applicable date and venue notices before visiting.')
page('activities.html','Activities',activities)

plan='''<div class="eyebrow">Dates / proposed framework</div><h1>Seven nights, thoughtfully.</h1><p class="lead">A workable date framework that includes the preferred 15–18 February period. It is a proposal, not a booked or transit-verified itinerary.</p>'''
plan+=section('The date options',table(['Proposed stay','Nights','What it resolves','Official context'],[['15–22 Feb 2027','7','Includes the preferred period; checkout on 22 February.',src(('State Council holiday notice',holiday))],['15 Feb–1 Mar 2027','14','A two-week alternative; checkout on 1 March.',src(('State Council holiday notice',holiday))],['16–23 Mar 2027','7','A later comparison window; checkout by 23 March.',src(('State Council holiday notice',holiday))]]),'These are planning scenarios, not price or availability findings.')
plan+=section('Suggested sequence',f'''<div class="panel"><ul class="list"><li><strong>15 February:</strong> arrival / check-in if confirmed. Shanghai Museum and Palace Museum normally close Mondays; verify any special opening.</li><li><strong>16–21 February:</strong> consider dining, museum visit and flexible time. Taian Table’s regular dinner bookings run Tuesday–Saturday. Do not allocate a slot without verified availability or route.</li><li><strong>22 February:</strong> seven-night checkout and departure if that date is booked.</li></ul><p>References: {link(sm,'Shanghai Museum')}, {link(pm,'Palace Museum')}, {link(faq,'Taian Table')}.</p></div>''')
plan+=section('When is cheapest to book?','''<div class="panel"><p><strong>Unverified.</strong> No official, date-specific seven-night quotes were obtained for the scenarios above; there is no basis to name a cheapest stay or future booking date. A forecasting claim requires observed comparable rate histories, not a single advertised nightly rate.</p><p>Record quote capture date and time, hotel, room, arrival and departure dates, two-adult occupancy, currency, total taxes/fees, cancellation policy and inclusions. Repeat the same quote across dates, then compare like for like. Rates and availability can change.</p></div>''')
page('plan.html','Trip plan',plan)

review='''<div class="eyebrow">Review / transparency</div><h1>What we still need to know.</h1><p class="lead">An honest decision log: verified facts are linked; unresolved fields stay unverified. Suggestions are proposals only, not implemented product decisions.</p>'''
review+=section('Flagged for review',table(['Issue','What is known / missing','Suggested discovery','Official source'],[['Hotel ranking and ≤60-minute travel','Hotel-to-restaurant / activity routes and counts are unverified.','Use a transit operator or authoritative route planner for each entrance-to-entrance journey at a documented departure time; then recount by distinction.',src(('Michelin Shanghai',sh),('Hyatt',park))],['Seven-night prices','Official two-adult, tax-inclusive 2027 prices and availability were not obtained.','Request identical dated quotes from the hotels and save evidence. Do not assume rooms are unbookable.',src(('Hyatt',park),('Four Seasons Beijing',beijing))],['Cheapest time to book','No observed comparative rate history.','Track repeated official quotes with dates, cancellation rules and taxes; compare equivalent rooms.',src(('Four Seasons Guangzhou',gu))],['Guide changes','2025 Shanghai press release describes 145 restaurants and two 3-star establishments; current online list shows 154 and one 3-star.','Different editions / snapshots; use current individual listing and recheck before departure.',src(('2025 Michelin release','https://guide.michelin.com/en/article/news-and-views/shanghai-2025-starred-restaurants'),('Current Michelin list',sh))],['Museum exhibition and hours','People’s Square site lists one exhibition through 14 November 2027 and evening sessions subject to updates.','Check museum notices, dates, tickets and hours before the visit.',src(('Shanghai Museum',sm))],['Social accounts','Official YouTube, TikTok and Instagram handles were not independently confirmed.','Search links are clearly labelled, not verified official handles.',src(('Taian Table',faq),('Shanghai Museum',sm))],['2027 dining prices and closures','Current reference menus and hours are not confirmed for travel dates.','Contact venues; obtain date-specific menu, taxes, special hours and reservation terms.',src(('Taian FAQ',faq),('Michelin King’s Joy',king))]]))
review+=section('Open questions & how to resolve them',table(['Question','Current answer','Discovery path','Relevant official source'],[['Which hotel has the most Michelin restaurants within 60 minutes?','Unverified. City totals do not answer this.','Build and verify the transit matrix; count by Michelin distinction.',src(('Michelin',sh))],['What is the full trip budget?','Unverified: no verified hotel, flight, transit or complete dining total.','Collect current dated official quotes and sum consistently in one currency.',src(('Four Seasons',gu))],['Which dates and city best fit the couple?','7- and 14-night scenarios fit the stated window; priorities and availability remain unknown.','Compare quoted itineraries, transit and attractions before selecting.',src(('State Council',holiday))],['Are entry documents and travel eligibility settled?','Unverified; nationality, residence, passports and routing are unknown.','Check the relevant Chinese embassy and airline entry rules for the travellers and route.',src(('China consular services','https://cs.mfa.gov.cn/'))],['Are dietary needs, accessibility, and booking conditions compatible?','Unverified for the travellers.','Confirm dietary accommodation, room accessibility, payment and cancellation directly with providers.',src(('Taian FAQ',faq),('Hyatt room details',park))]]))
review+=section('Suggestions for a future version',table(['Proposal','Decision value','Before implementing','Related official source'],[['Live, dated quote tracker','Makes price changes and comparable seven-night totals visible.','Confirm permitted collection, data freshness, terms and currency handling.',src(('Hyatt',park))],['Public-transit matrix & map','Enables the requested hotel ranking and one-hour validation.','Choose a reliable routing provider and define departure-time and walking assumptions.',src(('Michelin',sh))],['Alerts for status, menus and hours','Highlights changes before booking or travel.','Confirm data rights, update cadence and attribution.',src(('Michelin',bj),('Museum',pm))],['Side-by-side budget scenarios','Makes tradeoffs and all-in totals easier to inspect.','First collect equivalent verified hotel and restaurant prices.',src(('Taian FAQ',faq))]]))
review+=section('Verification method','''<div class="panel"><p>Research checked 25 November 2026 against the linked official operator, government or Michelin sources. Published restaurant stars are current page observations, not promises for 2027. Menu arithmetic explicitly multiplies the operator’s per-person reference price by two. Unverified fields are displayed as such; they do not signify zero or unavailability.</p><p>External sites can change, move, redirect, require JavaScript, region access or an account. Search links are for discovery, not factual evidence. The dataset is deliberately a limited sample, not a complete national search or a verified best-value ranking.</p></div>''')
page('review.html','Flagged for review',review)
print('Built',len(links),'pages')
